#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-11-12

<#
.SYNOPSIS
  Archive recipe (simple): copy the backup set to a destination, keep the last N.
.DESCRIPTION
  An archiver recipe. The engine passes a RecipeContext and runs its 'archive'
  step against the completed set in $ctx.OutDir (the service's stage dir). This
  copies the set into a timestamped directory under the destination and prunes to
  the newest N — a flat history, no tiers. Env (via $ctx):
    ARCHIVE_DEST  (required) destination base dir; the service name is appended.
    ARCHIVE_KEEP  (default 3) how many timestamped copies to keep.
  Layout: <ARCHIVE_DEST>/<service>/<yyyyMMdd-HHmmss>/<artifacts>
  Reports { path } back through $ctx.State.Result so the engine can log it.
#>

param($Recipe)

if ($null -eq $Recipe) {
    Write-Host 'This is a sequencer recipe; it is loaded by the engine, not run directly.'
    return
}

$Recipe.AddStep('archive', {
    param($ctx)
    $destBase = $ctx.RequireEnv('ARCHIVE_DEST')
    $keep = [int]($ctx.EnvValue('ARCHIVE_KEEP', '3'))
    if ($keep -lt 1) { $keep = 1 }

    $svcDir = Join-Path $destBase $ctx.Service
    New-Item -ItemType Directory -Force -Path $svcDir | Out-Null
    # name the copy by the run id, so an archive ties directly back to its run
    $stamp = if ($ctx.RunId) { $ctx.RunId } else { Get-Date -Format 'yyyyMMdd-HHmmss' }
    $target = Join-Path $svcDir $stamp
    New-Item -ItemType Directory -Force -Path $target | Out-Null

    # copy the complete artifact set from the stage dir into the timestamped copy
    Copy-Item -Path (Join-Path $ctx.OutDir '*') -Destination $target -Recurse -Force

    # prune by the recorded archive history (the log), never by dir names: keep the
    # newest N archives of this service, delete the recorded paths of the rest. We
    # only ever touch paths this archiver recorded, so foreign dirs are never at risk.
    $events = $ctx.ReadEvents()
    $prunedPaths = @($events |
            Where-Object { $_.type -eq 'service.archive-pruned' -and $_.PSObject.Properties['path'] } |
            ForEach-Object { $_.path })
    $live = @($events |
            Where-Object {
                $_.type -eq 'service.archived' -and $_.svc -eq $ctx.Service -and
                $_.PSObject.Properties['path'] -and ($prunedPaths -notcontains $_.path)
            } |
            Sort-Object { [datetime]$_.ts })   # oldest first
    $prunedNow = @()
    $over = ($live.Count + 1) - $keep           # +1 for the copy just made (not yet logged)
    if ($over -gt 0) {
        foreach ($old in (@($live) | Select-Object -First $over)) {
            if (Test-Path -LiteralPath $old.path) {
                Remove-Item -LiteralPath $old.path -Recurse -Force -ErrorAction SilentlyContinue
            }
            $prunedNow += $old.path
        }
    }

    $ctx.State['Result'] = @{ path = $target; pruned = $prunedNow }
})
